def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    positions = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                positions.setdefault(grid[r][c], []).append((r, c))

    for color, pts in positions.items():
        # A color occurring three times forms a corner/diagonal motif; extend
        # its diagonal pair outward from the lone cell.
        if len(pts) != 3:
            continue
        for r, c in pts:
            for dr, dc in ((1, 1), (1, -1)):
                if (r + dr, c + dc) in pts:
                    # Only extend the pair away from the third, adjacent mark.
                    other = next(p for p in pts if p not in ((r, c), (r + dr, c + dc)))
                    if abs(other[0] - r) + abs(other[1] - c) == 1:
                        rr, cc = r - dr, c - dc
                        while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                            out[rr][cc] = color
                            rr -= dr
                            cc -= dc
                    if abs(other[0] - (r + dr)) + abs(other[1] - (c + dc)) == 1:
                        rr, cc = r + 2*dr, c + 2*dc
                        while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                            out[rr][cc] = color
                            rr += dr
                            cc += dc
    return out
